import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易经传集解卷五","description":"周易经传集解 - 周易经传集解卷五","frontmatter":{"title":"周易经传集解卷五","description":"周易经传集解 - 周易经传集解卷五"},"headers":[],"relativePath":"zh/classics/jingchuan-jijie/006.md","filePath":"zh/classics/jingchuan-jijie/006.md"}'),r={name:"zh/classics/jingchuan-jijie/006.md"};function c(o,a,l,d,p,h){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易经传集解卷五",tabindex:"-1"},[n("周易经传集解卷五 "),e("a",{class:"header-anchor",href:"#周易经传集解卷五","aria-label":"Permalink to “周易经传集解卷五”"},"​")],-1),e("p",null,"钦定四库全书周易经传集解小畜履卷五 ​宋林栗撰。序卦曰：「比者，比也。比必有所畜，故受之以小畜。」「畜」之为义，说者曰：「止者，聚也、养也。」夫止者，「艮」之义也；聚者，「萃」之义也；养者，「颐」之义也。以之训「畜」，皆不固矣。至于圣人，亦岂云尔哉？曰：「比必有所畜」而已。稽其近似，盖有含畜之意焉。何则？实不能以畜实，虚则能之；刚不能以受刚，柔则能之。然则止也、聚也、养也，亦兼明之矣。自「比」之「畜」，「坤」变为「乾」，「坎」变为「巽」，而成卦也。天下之所以「比」于九五者，以天下皆柔，惟五之为刚也；天下皆弱，惟五之为强也。夫天下之人，岂尽柔弱而已乎？材智勇健，固不乏人矣。为九五者，岂必智勇出于其上而后为之君哉？其必有以畜之矣。梁襄王问于孟子曰：「天下乌乎定？」对曰：「定于一。」「孰能一之？」曰：「不嗜杀人者能一之。」「孰能与之？」曰：「天下莫不与也。」其比畜之义乎？是故自比之畜，变其四爻，其不动者，九五、六四矣。然则五之所以畜之者，非六四而谁欤？是故畜有大小，「大畜」，君也；「小畜」，臣也。以一阴而畜五阳，其小之何也？以其近君之位，而体柔巽之行，是以谓之「小畜」也。小畜：亨。密云不雨，自我西郊。彖曰：小畜，柔得位而上下应之，曰「小畜」。健而异，刚中而志行，乃亨。「密云不雨」，尚往也。「自我西郊」，施未行也。下乾上巽成卦曰「小畜」者，「乾」为健，「兑」为说，「离」为丽，「巽」为入。天下之健者，说而丽之，非有以「巽」而入焉，其能畜之乎？故曰：「小畜，亨。」以「巽」畜「乾」，以一柔畜五刚，小畜大之义也。畜大而能「亨」者，「柔得位而上下应之」也。六四也者，近君之位也。以六居之，得其位矣。上承九五，得其君也；下接三阳，得其助也。得其位，得其君，得其助，则天下聪明才智勇敢之士，莫不说而丽之，此其所以能「亨」也。故曰：「柔得位而上下应之，曰小畜。」夫六四者，畜之宗也。九五者，畜之主也。四之畜之也，岂自为哉？凡以九五之故也。五虽中正，以健制健，必不畜矣；以刚御刚，必不容矣。今健而下「巽」，刚中而志行，是以畜而亨也。故曰：「健而巽，刚中而志行，乃亨。」「密云不雨，自我西郊」，何谓也？曰：云雨，「坎」也。「小畜」反复八象，未尝有「坎」，而彖言「密云不雨」，四言「有孚，血去惕出」，上言「月几望」，皆「坎」象也。学者可不求其故哉？或曰：「敢问其故？」曰：「小畜」之「坎」，由比来也。观夫序卦，则得之矣。比之六四、上六，「坎」也。其九五，坎之中爻也。自比之畜，不变者二爻耳。是以上卦之「巽」有坎象焉，明其所从来也。或曰：「凡卦之象，莫非有所从来也。既以为小畜矣，而犹有比象，其在他卦，何独不然？」曰：他卦亦固有之，不若小畜之象，全取乎比也。所以然者，何哉？为其畜之故也。比而后畜，则巽之有坎，不亦宜乎？或曰：然则安在其为密云而不雨也？曰：为其畜之故也。坎变为巽，而在乾之上，云雨之气既升乎天，以一阴而受五阳之归，是以盘旋蓊郁，畜为云密，而膏泽不下流也。其曰自我西郊，何也？曰：「我」，六四也。六四视二为「兑」，视上亦为「兑」。「兑」，西方也。「坤」之彖曰：「西南得朋，乃与类行。东北丧朋，乃终有庆。」是故天气下降，地气上腾，阳居其所，阴丧其朋，然后云行而雨施。今六四之「巽」，既上腾矣，然而未离其类，自我西郊，是以屯其膏而未下也。子曰：「密云不雨」，尚往也。「自我西郊」，施未行也。尚往之为言，犹言乃与类行云尔。自我西郊，而未达于东北，施之未行，不亦宜乎？东北，「艮」也，自东北而震也。夫「畜」以「艮」畜「乾」，而九三、上九皆有「震」体，此其所以异于「小畜」欤？象曰：风行天上，「小畜」，君子以懿文德。「天」者，「乾」也。「风」者，「巽」也。「风行天上」，则为发号施令之象；行于地上，则为观民设教之象。今也行于天上，其犹号令之未发，政教之未施乎？固已畜之于此矣。惟天为大，而风行其上，小之畜大，亦如是也。故君子象之，「以懿文德」。「懿」之言美也。美其文德，以发号施令，观民设教，无适而不宜矣。杂卦曰：「小畜，寡也。」「畜」之为卦，以柔畜刚，以「巽」畜「乾」也。夫「乾」，天下之至健也，而「巽」之长女以柔畜之，「乾」之受制，不亦难乎？然卦惟一柔，而诸爻皆刚，以刚遇刚，不能相下，其势必归于柔。以五刚而归一柔，柔至寡而刚至众，欲无受畜，不可得矣。是故阳见乘陵则为「反目」，阴能乘顺则为「挛如」，远而相得则为「复道」，同体而相说则为「牵复」，为「载德」，皆即六四以言其义也。然则以一柔而畜五刚，非至寡，其孰能之？初九：复自道，何其咎？象曰：「复自道」，其义吉也。初九，「乾」也。以阳居刚，而在一卦之下，应乎六四之「巽」，故曰「复自道」。「乾」之九三，「终日乾乾」，其象曰：「反复道也。」今初九之「乾」，方受六四之畜，未可以进，复自道而已，故曰：「何其咎，吉。」初在一卦之下，体乎「乾」刚，复自其道，又何咎之有哉？既免于咎，斯为吉矣。方畜之时，一阴在上，牵制群动，初九之君子虽在下位，与之为应，但能反复其道，无所迎将，吉孰如之？故子曰：「复自道，其义吉也。」九二：牵复，吉。象曰：「牵复」在中，亦不自失也。九二，「兑」也。以阳居柔而在下卦之中，上无其应，而连于六四之「巽」，故曰「牵复」。「牵」，连也。二四同体，故有「牵复」之象。君子在下，不得于君而得于大臣，虽为所牵，而能居中守正，反复其道，不为屈挠，牵而能复者也，故曰「吉」。子曰：「牵复在中，亦不自失也。」以其居中，知其能自免矣。九三，舆说辐，夫妻反目。象曰：「夫妻反目」，不能正室也。九三下体为「乾」，上体为「离」，以阳居刚而在下卦之上，上无其应，承于六四之「巽」，故曰「舆说辐」。「巽」、「离」、「兑」皆出乎「坤」，「坤」为大舆，「离」为丽，「巽」为入，为伏，故有「舆说辐」之象。「说辐」则舆不行矣。其所以说辐而不行者，则受畜故也。夫「舆」之言众也，其象车也。象载车而行，是必人之豪杰、师之尊长也。说辐而受制，是必有其道矣。九二之舆，已有毁拆之象，而未遇其配，志犹上行。至于九三而遇六四，「离」「坎」相合，则说其舆辐矣。三说其辐，则二之牵复不亦宜乎？然三同志上行，受畜于四，岂其所愿哉？故曰「夫妻反目」。「离」为目，「坎」为青，「巽」为多白眼，故有「夫妻反目」之象。「反目」，怒而相睨，则乖阂之睛也。六为畜之宗，处九于五而自下畜之，则上下相安而有挛如之孚，善畜君者也。若处九于三而自上畜之，则是妇制其夫，臣制其君也。三以「乾」之刚，以「离」之明而受畜于四，又见其陵，则其不和而反目宜矣。是以圣人体天地，法阴阳，制为夫妇室家之礼，刚上而柔下，男行而女随，然后可以长久而无乖阂之患。故子曰：「夫妻反目，不能正室也。」谓九三在下而六四在上故也。六四：有孚，血去惕出，无咎。象曰：「有孚」「惕出」，上合志也。六四上体为「巽」，下体亦为「巽」，以阴居柔而在上卦之下，应乎初九而介于九三、九五之间。初与三为「乾」，三与五为「离」，故曰「有孚，血去惕出，无咎」。四之为「巽」，由坎变也。「坎」为有孚，为「血」，为「惕」。「有孚」谓承五也，「血」「惕」，谓乘三也。「血」之言「惕」，「惕」之言惧也。六四在「比」，既以「孚」为九五矣，至畜而成刚，故有相惧之象焉。谓其既比为五，而能「巽」以畜之，志同义合，诚信已孚，则祸患之来，不旋踵而自去，忧惧之至，不转瞬而自消。所以然者，「坎」变为「巽」故也，故曰「无咎」。子曰：「有孚惕出，上合志也。」居近君之位，持宰物之权，上下五阳，唯己之听，欲无伤惧，不亦难乎？唯其尽忠竭诚，与上合志，使谗间之口不能得其隙而议之，然后可以免矣。九五，有孚挛如，富以其邻。象曰：「有孚挛如」，不独富也。九五，「离」也。以阳居刚，而在上卦之中，下无其应，而乘六四之「巽」，故曰「有孚挛如」。「挛」，犹纳也。易以远而配为「交如」，近而合为「挛如」，言绸缪固结也。六四之「巽」，犹有「坎」象，其过九五，「离」「坎」相合，可谓「挛如」之孚矣，故曰「富以其邻」。阳为富，阴为贫。「以」，犹用也，邻犹臣也。书曰：「钦四邻。」又曰：「臣哉邻哉！邻哉臣哉。」以其密迩于五，故以邻言之矣。六四者，畜之宗也，本乎阴虚，故能受众阳之归。然岂将据而有之哉？盖以九五在上，有智勇过人之资，苟与天下争能而角技，则天下之智勇未必皆「比」，其下将不必服而臣之矣。是故用其柔「巽」以畜纳之，使下之智勇不以犯其上，上之智勇不以胜其下，上安于为君，而下安于为臣。故六四之畜，凡以为九五之用也。书曰：「如有一个臣，其心休休焉，其如有容。人之有技，若己有之；人之彦圣，其心好之，不啻如自其口出，是能容之，以保我子孙黎民。」其六四之谓欤？然九五方受畜于四，而乃能用之，何哉？以其富也。贵为天子，富有天下，而乐与贤者共之，是以能用之也。子曰：「有孚挛如，不独富也。」富也者，人主之所独也。「乐与贤者共之」，则贤者乐为之用，安富尊荣，有隆无替，岂与愚夫愚妇独富而无邻者同日语哉？上九：既雨既处，尚德载，妇贞厉，月几望，君子征凶。象曰：「既雨既处」，德积载也；「君子征凶」，有所疑也。上九，「兑」也。以阳居柔，而在一卦之上，下无其应，而连于四之阴，乘乎五之阳，故曰「既雨既处」。夫「巽」「离」「坤」「兑」者，阴之所也；「乾」「坎」「艮」「震」者，阳之方也。阴离其类也，而之乎阳，阴阳和而后雨。今「小畜」之阴，由「巽」而之「兑」，是以「畜」为「密云」而已。然「小畜」以柔畜刚，下之三阳，臣也；以臣畜君，上之九五是也。上九一爻，乘九五之刚，而受六四之畜，将何义以处之？其臣之元勋旧德，人主所尊尚者欤？说以从巽，斯受其畜矣，故以「既雨」之义明之。四之为「巽」，由坎变也。自坎而之「巽」，自「巽」而之「兑」，其「既雨」而复其所乎？既雨而复，则功臣之象也，故曰「尚德载」，畜德之盛而天下载之，是以九五尚之也。夫以人臣而居成功之地，有积德之名，世主之所忌也。不能奉身以退，而犹贞固守之，危之道也。故曰：「妇贞厉，月几望，君子征凶。」离为日，「坎」为月。月之望与日为衡，分天之中，故谓之「望」。望则疑为日矣。日中则昃，月盈则亏，天之道也。月之几望，其极盛之时乎？君子不戒而征，则凶矣。君子者，对妇而言也。在家为夫妇，在国为君臣，圣人之所以为戒深矣。故子曰：「既雨既处，德积载也。君子征凶，有所疑也。」德盛而名尊，位高而权重，有疑阳之势矣。序卦曰：「物畜然后有礼，故受之以履。」「履」之成卦，畜之反也。「履」之三，即「畜」之四也。「履」之兑，即「畜」之「巽」也。夫以一阳而为五阳之主，虽非天位，而五阳居之，在四而能畜者，当位而承乎五也。今居三不当其位，不承九五，以为君则不正，以为臣则不顺，故不足以主一卦之义，而取其上下二体，名之曰「履」焉。「乾」者，阳之至尊；「兑」者，阴之至卑。莫高乎天，莫下乎泽。上安其尊，下守其卑。君子履之，臣民藉焉，斯之谓「履」矣。夫天下才智勇敢之士，莫不有上人之心。及其未受畜也，跳踉咆哮，无所不至；及其既畜矣，入吾含畜之内，然后上下之分定，而礼行乎其间矣。是故「乾」以健而行，「兑」以说而应。虽其下有二阳，而安为之藉，莫有争心，斯以履、以畜之义也。履虎尾，不咥人，亨。彖曰：「履」，柔履刚也。说而应乎乾，是以「履虎尾，不咥人，亨」。刚中正，履帝位而不疚，光明也。下兑上乾成卦曰「履」者，初为「兑」，二为「离」，三为「巽」，四为「乾」，五为「兑」。巽、离、兑为三女，言「乾」则包三子，言「三女」则包「坤」。三阳在上，三阴在下，尊卑之分不既明矣乎？是以谓之「履」也。故曰：「履，柔履刚也。」柔履乎刚，「履」之象著矣。夫「履」之为言，自上履下也。不曰「刚履柔」，而曰「柔履刚」者，犹孟子「小役大，弱役强」之义。刚之履柔，以势言之也。柔履于刚，心说而诚服矣。谓之有礼，不亦宜乎？「履虎尾，不咥人，亨」，何谓也？曰：乾为人，「兑」为虎。虎，阴物也；「兑」，西方之卦，有虎之象焉；又为口，有咥之象焉。「乾」在其上，有「履虎尾」之象焉。履虎之尾，其首必反，未有不见咥者也。而又言「不咥人，亨」，何也？为其既已畜之矣，驯习于人，履之而不咥，宜哉！传曰：「虎之与人异类而婿养。」异者，顺也。婿犹说也，顺犹「巽」也。此「巽」之所以为「畜」，而「兑」之所以为「履」也。故曰：「说而应乎乾，是以履虎尾，不咥人，亨。」彼说而应乎我，故履之而不吾咥也。履之而不吾咥，足以为无咎而已，何自亨哉？夫子于是发明之曰：「刚中正，履帝位而不疚，光明也。」所以释「亨」之义也。「乾」之三阳，有相终始之义。「刚中正」谓五也，以九居五故也。「履帝位」，谓上也，履乎天位故也。「不疚光明」，谓四也，体乎离明故也。「履虎尾而不咥」，则「刚中正，履帝位而光明不疚」，不亦亨乎！象曰：上天下泽，「履」，君子以辨上下，定民志。「天」者，「乾」也；「泽」者，「兑」也。莫高乎天，莫下乎泽，君子体之，「以辨上下」，而民志定矣。杂卦曰：「履，不处也。」「履」之为卦，上休履下也。其在六位，上爻履下爻也。以刚履刚，得所履则吉；以柔履刚，以刚履柔，失其所履，则有虎尾之厉焉。「履虎尾」，宜见咥者也。履之而不见咥者，履而不处，九四是也。若履而处之，咥人宜矣。阳为行，阴为处。五阳之爻皆「吉无咎」，而六三独凶者，谓其履而处之也。初九：素履，往，无咎。象曰：「素履」之往，独行愿也。初九，「兑」也。以阳居刚，而在一卦之下，上无其应，下无所履，而承于九二之「离」，故曰「素履」。「兑」，西方之卦，而色白，有「素履」之象焉。「履」以所履之爻为义，既无所履，则取其所往，以阳居刚，履得其正，而谓之「素履」焉。贤人君子，身处卑贱，见履于人，遗逸而不怨，厄穷而不闵。履其素而已履者，礼也。燔兔匏叶，可以行礼；啜菽饮水，可以事亲。君子所履，于是素矣。素履而行，何咎之有？子曰：「素履之往，独行愿也。」君子得其时，得其位，推其所履以兼善天下，岂非素愿也哉？不得其位，不得其时，独行诸身而已，岂往而求之哉？九二：履道坦坦，幽人贞吉。象曰：「幽人贞吉」，中不乱也。九二，「离」也。以阳居刚，而在下卦之中，上有九五而非其应，乘初九之刚，而履于六三之柔，故曰：「履道坦坦，幽人贞吉。」「离」也者，明也。日中而行，得其所履坦坦之道也。既以体乎离明，而履坦坦之道，宜若可以行矣，而乃曰「幽人贞吉」，何也？为其以九居二，远不应五，而近臣六三，三之眇跛，不足与有为也。往而从之，陷于乱人矣。惟幽潜之君子，为能贞固守之，斯为吉也。或曰：离为明，坎为幽，二体「离」而谓之幽人，则「离」、「坎」之象可以互用乎哉？曰：以幽而眩明，其明乃所以为幽也；以明而守幽，其幽祗所以为明欤？以九居二，故有幽人之象也。或曰：初无所履而犹往无咎，二得其所履而不保其往，何也？曰：初处最下，远无所应，近无所承，其往也，独行其素而已，必「无咎」也。若夫九二履于六三，阴阳相求，物之情也。二之往也，非三而谁从？故必贞而后「吉」也。子曰：「幽人贞吉」，中不自乱也。卦惟一阴，而九二承之，乌知其「贞吉」而不为「贞凶」也哉？其以刚中，知其不自乱矣，是其所以为「贞吉」者也。若利害得丧乱于其中，尚能守其中贞也哉？六三：眇能视，跛能履，履虎尾，咥人，凶。武人为于大君。象曰：「眇能视」，不足以有明也。「跛能履」，不足以与行也。「咥人」之凶，位不当也。「武人为于大君」，志刚也。六三上体为「巽」，下体为「巽」，以阴居刚，而在下卦之上，视二为「离」，视四亦为「离」。视初为「兑」，视五亦为「兑」。故曰：「眇能视，跛能履。」「离为目」，「巽为多白眼」，眇而能视也。「巽为股」，「兑为毁折」，跛而能履也。为其阴柔不中不正，故以眇跛言之也。故曰：「履虎尾，咥人凶。」「兑为虎」，三履其中，以柔履刚，失其所履，「履虎尾」也。「兑为口」，「巽」为入，入于虎口，咥人之象也。虎之踞也，其尾旋焉，是以既为尾，而又为口也。巽为伏，为进退，为不果。阴柔之性，贪利忘反，见难而不能去，履而处之之象也。夫眇而不能视，跛而不能履，则安分而止矣，岂有虎尾之忧哉？为其眇而自以为能视，跛而自以为能履，故冒险而行，履虎尾而不知危也。履乎虎尾，明不足以见，强不足以行，履之而不去，安有不见咥者？或曰：「武人为于大君」，以六居三，不当其位，小人而乘君子之器，「武人为于大君」之象也。以独阴居下卦之上，在五阳之中，视天下莫己若，遂有为大君之志，不知其所履者，天下之至危也。武而无谋，履非其据，足以杀其身而已矣。夫六三者，小畜之六四也。自畜而履，保其常心，则彖所谓「说而应乎乾」者也。说而应乎乾，则上下辨而民志定矣。而三以重巽之体，居离兑之中，不能自克，以及于难，故九五于三「旋其吉」，而上九于三「考不祥」。吉凶无常，唯所召耳。子曰：眇能视，不足以有明也；跛能履，不足以与行也。咥人之凶，位不当也。「武人为于大君，志刚也。」三在二四之中，而有应在上，此其所以有为君之质，虽柔而求至刚矣，是以谓之「武人」也。若以六居五，履信而思顺，当位而尚贤，以一阴为众阳之归，岂有武人之象哉？九四：履虎尾，诉诉，终吉。象曰：「诉诉终吉」，志行也。九四上体为「乾」，下体为「离」，以阳居柔而在上卦之下，履六三之柔，而履于五之刚，故曰：「履虎尾，诉诉，终吉。」三，「兑」也，终「兑」为虎，四履其上，以刚履柔，失其所履，「履虎尾」也。「诉」与「溯」同，「溯」犹行也。溯溯，行而不止也。三之阳而上行，故有「溯溯」之象。「乾」为刚，「离」为明，明足以见，刚足以行，是以知危而不履也。在「兑」之上，已进乎「乾」，履而不处，说乎虎口矣。说乎虎口，未可以言吉，吉在其终也。子曰：「诉诉终吉，志行也。」志在于行，说乎虎口，至于上九，而后「元吉」以终之。此彖所谓「不咥人亨」者欤？九五：夬履，贞厉。象曰：「夬履贞厉」，位正当也。九五，「兑」也。以阳居刚，而在上卦之中，承柔皆刚，得其所厉矣，故曰：「夬履，贞厉。」「夬」之言决也。在易之「夬」，刚决柔，「乾」决兑也。九五在上，而六三「武人欲为大君」，当是之时，可以决而去之矣。「夬」之九五所以不利即戒者，以至刚而决至柔，以至盛而决至衰。物极则反，人穷则诈，有危道焉。故曰：「中行无咎，中未光也，」谓其健而不说，决而不和也。至「履」之九五，本刚健之资，而体乎柔说之道，故曰：「刚中正，履帝位而不疚。」光明也，谓其健而说，决而和也。是故「履」皆以「乾」决「兑」，而「履」之五有「兑」象焉。以「乾」决「兑」，犹惧其危；以「兑」决「兑」，蔑不济矣。然则系之「贞厉」，何也？凡易言「贞」与「征」，为相反之辞。「征」犹行也，贞犹固也。以征为凶者，以贞为吉；以贞为厉者，以征为亨也。养虎为患，前志所戒，五之「贞厉」，不亦宜乎？子曰：「夬履贞厉，位正当也。」以五之正当，决三之不当，可以决之而无疑矣。然犹贞固守之，长奸纵恶，危之道也。上九：视履考祥，其旋元吉。象曰：「元吉」在上，大有庆也。上九，「乾」也。以阳居柔，而在一卦之上，「履」乎九五而不为人之所履，故曰：「视履考祥，其旋元吉。」上履之终也，以柔济刚，履道之成也。「履」乎九五，履天位也。以刚履刚，得其所履，可以安行矣。然犹视而后履，谨之至也。书曰：「若跣弗视地，厥足用伤。」视「履」之谓也。视言柔，「履」言刚也。九四、上九皆得之矣。九四视而后履者，虽未免虎尾之危，其觉而去速矣。六三之视「履」，所谓眇者不足以与明，跛者不足以与行也。至于九四，体「离」之明，体「乾」之健，以「离」而视，则无不察矣；以「乾」而「履」，则无不亨矣。然而非其所履，未可以言吉也。至于上九，卦之终也。兢兢业业，谨终如始，上九之谓也。视履之祥，至于此而后见也。考之为言，成而可校也。祥之为言，善而得福也。旋之为言，反而有归也。福善祸淫，天之道也。然为善者，有时而逢殃，为恶者，有时而获福。是以世之人疑焉，盖不考之于其旋故也。考其旋，则善恶之报无不验矣。君子之为善也，非以侥幸于目前之福也。择而履之，一举足不敢易也。凛然如履虎尾而将咥人，是以见利而思害，临福而忧祸。思则利有所不就，忧则福有时而辞之，较之目前，有不及宜行者矣。及其旋而考之，元吉之所归也。此文王、孔子之所以行乎忧患，而不改其操也欤？故曰：「履，德之基也。」视而后履，所以为德之基也。又曰：「履和而至」，以兑济乾，以柔济刚，所以为和而至也。又曰：「履以和行，始乎诉，诉中吉，终乎视履，所以和其行。至于上九，其裕后矣。积善之家，必有余庆，不在其身，必在其子孙也。谓之元吉，不亦宜乎？」子曰：元吉在上，大有庆也。上九体乾，乾为大，应在六三，阴阳相得，谓之大有庆。夫以五之中正，宜元吉矣。今元吉犹在上者，谓其大而且有庆也。不计目前之福，而考之于其旋，子孙之庆，宁有穷乎？此之谓大有庆也。非文王之孙子，其谁足以当之哉？履卦序说。子曰：「易有太极，是生两仪，两仪生四象，四象生八卦，八卦定吉凶，吉凶生大业。有物混成，是谓太极。天尊地卑，是谓两仪。坎、离、震、兑，是谓四象。乾、坤、艮、巽，是谓八卦。」然子言「易有太极」，以至「吉凶大业于是乎生」。前此数者，既已兴于爻象之中矣。愚读易至履卦，始得四象、八卦之说，知圣人之所以示我者，独详言之。今夫总六画而成卦，谓之履者，太极之象也。系之曰：「兑下乾上者，两仪之象也。」初至三为「兑」，二至四为「离」，三至五为「巽」，四至上为「乾」，此则「两仪生四象」也。初为「兑」，五亦为「兑」；二为「离」，四亦为「离」；四为「乾」，上亦为「乾」。惟六三一卦，上体为巽，下体亦为巽。此则四象生八卦也。八卦成，而吉凶可定，吉凶定，而后大业于是乎生矣。是故四象者，卦之所以立也；八卦者，爻之所以分也。不知四象，无以尽一卦之性；不知八卦，无以辨六爻之情。八卦之在四象，犹八极之在四方也。言四象，则八卦在其中矣。故曰：「易有四象，所以示也；系辞焉，所以告也；定之以吉凶，所以断也。」夫四象者，于数为七八九六，于时为春夏秋冬，于象为金木水火，于德为仁义礼智。然而是数者，易之所以非其所有也。易之所藏，非其所示也。若夫有而示之，则于前之所陈非邪？凡易之中有是四象，所以示人者也。虽以示之，未之能察也，圣人又系之辞焉，如「履虎尾」、「素履」之类，所以告之也。虽以告人，未之能决也，圣人又定之以吉凶，如「不咥人，亨，往无咎」之类，所以断之也。圣人之为后世君子，可谓忧之深而爱之笃矣。子曰：「文王既没，文不在兹乎？天之将丧斯文也，后死者不得与于斯文也。」虽然，「苟非其人，道不虚行。」颜氏之子不幸早世，仲尼之所为恸哭也。盖家语所载者，商瞿子木受易于夫子，虽其学于今无传，然汉之言易者，皆本其所自出也。愚尝疑之。子木之贤，与其答问于孔子之书，夫岂人不足列于高弟，而乃以微言奥旨传之欤？世人有子夏易说者，其缪妄可读而知矣。旧传韩婴、丁宽所著，已不可考，恐今本又非昔书。近人晁说之以道自著其说，名曰商瞿易传，子夏之书，亦其类欤？按春秋左氏，卜筮之家，颇用四象，至汉以来，言易者谓之五体。而郑玄、虞翻、王肃之流，穿凿傅会，千岐万辙，使学者无所依据，然后王弼一举而废之。夫易，象也，废虞、郑之言可矣，而可以废圣人之言乎？且其言曰：「蹄者所以取兔，得兔而忘蹄；筌者所以取鱼，得鱼而忘筌。」然则舍筌蹄而求鱼兔，弼亦知其不可矣。自仲尼没千有余年，斯文幸而未丧，然圣人之意湮没不明，其去亡盖无几。近世易家颇悟王弼之失，恨其烛理不明，顾乃采拾魏、晋诸儒之谈，王弼已弃之糟粕，更取而陈之，其为后学诋诃，无足怪者。然孟子有言：「理义者，人心之所同然者也。」今之学者，虽狥王弼之陋，至于互体，时有所合，未尝不致疑焉。然其心以为圣人之所未尝言，而互体之说无一定之据，不若王氏之简且便也。呜呼！此岂学者之罪哉！今故取仲尼四象八卦之文，略陈梗槩，览者得以考焉。或问曰：「四象八卦，如子之言，则圣人曷不明以告人乎？」应之曰：「昔者伏羲氏始画八卦也，未尝有六画也，而文王重之。夫六画者，非文王之所造也，自伏羲而有之矣。文王之为六十四也，未尝有兑下乾上也，而夫子陈之。夫兑下乾上者，非夫子之所造也，自文王而有之矣。文王之言曰履虎尾，不咥人，亨者，由履之成卦而言之也。夫子之言曰：说而应乎乾上天下泽，履者，由兑下乾上而言之也。今之所谓四象八卦者，夫子既言之矣，小子述焉。如使圣人一一而告之，则伏羲以来有不胜言者矣。」或者又曰：「圣人之经不可使易知，其言曲而中，其事肆而隐，举一隅不以三隅反，则不复也。今子发圣人之奥而举其四隅，毋乃非圣人之意欤？」应之曰：「然，吾罪也夫，吾罪也夫！虽然，吾有不得已也。自仲尼没千有余年，未有能以一隅反者，幸而得之，又将隐而藏之，吾惧失圣人之意也，敢求明哲，以正斯言。」绍兴甲戌秋九月，崇仁学易堂书。周易经传集解卷五。",-1)])])}const _=t(r,[["render",c]]);export{m as __pageData,_ as default};
